dict.string:
.navbar {
	font-family: 'Courier New', Courier, monospace, serif;
	font-size: 1.1em;
	color: #AFAA9F;
	margin: -2px 0 0 0px;
	line-height: 20px;
	padding: 0 0 12px 0;
	font-weight: bold;
	background-image: url(navfill-v2.jpg);
}

.navbar-bg {
	text-align: left;
}

.navbar-bg ul {
	list-style: none;
	margin: 0px;
	padding: 0 10px 0 30px;
}


li {
	list-style-type: none;
	display: inline;
	padding: 0px 25px 0 0;
}


li a {
	text-decoration: none;
	color: #AFAA9F;
}

li a:visited {
	text-decoration: none;
	color: #AFAA9F;
}

li a:hover{
 	color: #D64600;}


li.current-page a{	 color: #fff;}
